window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[178]={"id":"178","numero":178,"titre":"Risques émergents","objectifs":[{"id":"178-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un risque émergent","contenu":"<div class=\"notion-course\"><ul><li>Une infection émergente est nouvellement apparue, nouvellement reconnue, ou augmente en incidence/extension ; une infection connue qui réapparaît est réémergente.</li><li>Mécanismes : changements de l’agent, des hôtes, des vecteurs et de l’environnement, mobilités, contacts humains–animaux, fragilisation des systèmes de santé et résistances.</li><li>Décrire agent, transmission, population exposée, gravité et incertitudes. Le caractère émergent n’implique ni <span class=\"nc-red_bg\">transmission interhumaine</span> efficace, ni forte létalité.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une infection émergente","contenu":"<div class=\"notion-course\"><p>Une <strong><span>maladie infectieuse émergente</span></strong> (MIE) est une maladie infectieuse (ou présumée infectieuse) à la fois <strong>nouvelle</strong> et <strong>en augmentation</strong>, touchant <strong>l'homme, l'animal ou <span>les</span> deux</strong>.</p>\n      <p>Une MIE peut correspondre à <strong>trois situations</strong> :</p>\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>Précisions</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"nc-yellow_bg\">Entité clinique d'origine infectieuse </span><strong><span class=\"nc-yellow_bg\">nouvellement apparue ou identifiée</span></strong></td>\n            <td>Pathologie jamais décrite ou identifiée auparavant</td>\n            <td>Infections respiratoires graves à <span>coronavirus</span> : <span><span class=\"nc-red nc-bold\">SRAS</span></span> (2003), <span><span class=\"nc-red nc-bold\">MERS</span></span> (Moyen-Orient depuis 2012), <span><span class=\"nc-red nc-bold\">COVID-19</span></span> (depuis fin 2019)</td>\n          </tr>\n          <tr>\n            <td>Maladie <strong>connue</strong> devenue MIE</td>\n            <td><strong><span>Incidence</span> :</strong> en augmentation<br><strong>Modification :</strong> des caractéristiques cliniques ou évolutives dans un espace / une population donnée<br><strong>Nouveaux variants</strong> de l'agent : modification de la <span>sensibilité aux anti-infectieux</span> (ex. BHR à risque épidémique) ; modifications antigéniques (moindre efficacité vaccinale ; nouveaux mécanismes pathogéniques type production de toxine)</td>\n            <td><span>West Nile</span> ; <span>Chikungunya</span> ; <span>Zika</span> ; <span>Ebola</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-yellow_bg\">Maladie identifiée dont </span><span><span class=\"nc-yellow_bg\">les</span></span><span class=\"nc-yellow_bg\"> </span><strong><span class=\"nc-yellow_bg\">conditions d'expansion sont réunies</span></strong></td>\n            <td><span class=\"nc-green nc-bold\">Optique d'</span><strong><span class=\"nc-green nc-bold\">anticipation</span></strong></td>\n            <td>Implantation d'<span><em>Aedes albopictus</em></span> dans le Sud de la France — moustique vecteur de la <span>dengue</span> et du <span>Chikungunya</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : une MIE n'est <strong>pas forcément une maladie nouvelle</strong>. Une maladie connue qui réémerge ou dont <span>les</span> conditions d'expansion changent est une MIE — exclure une maladie « pas nouvelle » est un <span>faux raisonnement</span> en QRM.</div>\n      <div class=\"callout callout-info\"><strong>Pour info (rang C — hors programme strict).</strong> L'émergence est un phénomène <span>dynamique et complexe</span>, résultant de l'interaction de la triade <strong>Hôte ↔ Agent <span>biologique</span> ↔ Environnement</strong>. Principaux facteurs favorisants : changements environnementaux (climat, déforestation, pression de sélection antibiotique) ; <span>évolution</span> démographique et urbanisation ; mondialisation des échanges et transports internationaux ; <span>contact</span> homme / faune sauvage ou <span class=\"nc-orange_bg\">animaux</span> domestiques ; modifications économiques et sociales ; pratiques médicales.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-3","rang":"B","rubrique":"Définition","titre":"Citer les principaux agents infectieux émergents ou réémergents","contenu":"<div class=\"notion-course\"><p><span>Les</span> agents <span>infectieux</span> émergents ou réémergents se répartissent entre ceux <strong>communs</strong> aux MIE et aux maladies hautement transmissibles, et ceux <strong>spécifiques</strong> aux MIE.</p>\n      <table>\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(<span>MIE</span> et maladies hautement transmissibles)</td>\n            <td>\n              <strong><span class=\"nc-red_bg\">Fièvres hémorragiques virales</span> :</strong> <span><span class=\"nc-red nc-bold\">Ebola</span></span> ; <span><span class=\"nc-red nc-bold\">Marburg</span></span> ; <span><span class=\"nc-red nc-bold\">Crimée-Congo</span></span> ; <span><span class=\"nc-red nc-bold\">Lassa</span></span><br>\n              <strong>Coronavirus émergents graves :</strong> <span><span class=\"nc-red nc-bold\">SRAS</span></span> ; <span><span class=\"nc-red nc-bold\">MERS</span></span> ; <span><span class=\"nc-red nc-bold\">COVID-19</span></span><br>\n              <strong><span><span class=\"nc-purple_bg\">Tuberculose</span></span> résistante :</strong> multi-résistante (<span><span class=\"nc-red nc-bold\">MDR</span></span>) ou ultra-résistante (<span><span class=\"nc-red nc-bold\">XDR</span></span>)<br>\n              <strong>Grippes :</strong> <span><span class=\"nc-purple_bg\">grippe aviaire</span></span> et <span><span class=\"nc-purple_bg\">grippe pandémique</span></span> (<span><em>Myxovirus influenzae</em> H5N1</span> et futures souches porteuses d'autres H et N)\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span>MIE</span></td>\n            <td>\n              <strong><span class=\"nc-purple_bg\">Encéphalites virales</span> :</strong> virus <span>West-Nile</span> ; virus <span>Nipah</span> ; virus <span>Hendra</span><br>\n              <strong><span class=\"nc-purple_bg\">Arboviroses</span></strong> (transmises par <span><em>Aedes aegypti</em></span> et <span><em>Aedes albopictus</em></span>) : <span>Chikungunya</span> ; <span>dengue</span> ; <span>Zika</span><br>\n              <strong><span>IST</span> :</strong> <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span><span class=\"nc-purple_bg\">syphilis</span></span> ; <span><span class=\"nc-purple_bg\">lymphogranulomatose vénérienne</span></span><br>\n              <strong><span class=\"nc-purple_bg\">SHU</span></strong><span class=\"nc-purple_bg\"> (syndrome hémolytique et urémique)</span> : <span><em>E. coli</em> O157:H7</span><br>\n              <strong><span class=\"nc-red_bg\">Infections graves à </span><span><em><span class=\"nc-red_bg\">Clostridium difficile</span></em></span> :</strong> <span><em>C. difficile</em> O27 hypervirulent</span><br>\n              <strong>BHR</strong> (bactéries hautement résistantes) : entérobactéries productrices de <span>carbapénémase</span> ; <span>entérocoque</span> résistant aux <span>glycopeptides</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span>Méningite</span> - <span>méningoencéphalite</span> · 159 — <span><span class=\"nc-purple_bg\">Tuberculose</span></span> Enfant / Adulte · 166 — <span>Grippe</span> · 167 — Hépatites virales · 169 — VIH · 176 — <span>Diarrhée</span> infectieuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une maladie hautement transmissible","contenu":"<div class=\"notion-course\"><ul><li>Une menace infectieuse se caractérise par son potentiel de diffusion, sa gravité et les moyens de contrôle disponibles. L’absence de traitement ou de vaccin n’est pas un critère obligatoire : des infections à haut risque disposent désormais de vaccins et/ou traitements.</li><li>Reconnaître rapidement exposition compatible et signes évocateurs ; protéger le patient et les soignants avec les précautions adaptées au mode de transmission.</li><li>Alerte selon le circuit ARS/Santé publique France et recours aux équipes spécialisées ; les mesures doivent suivre l’agent et le contexte épidémiologique actuels, sans considérer toutes les infections émergentes comme également contagieuses.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-5","rang":"B","rubrique":"Définition","titre":"Citer les principaux agents infectieux responsables de maladies hautement transmissibles","contenu":"<div class=\"notion-course\"><p><span>Les</span> agents responsables de maladies hautement transmissibles se répartissent entre ceux <strong>communs</strong> aux MIE et ceux <strong>spécifiques</strong> aux maladies hautement transmissibles.</p>\n      <table>\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(partagés avec <span>les</span> <span>MIE</span>)</td>\n            <td>\n              <span><span class=\"nc-red_bg\">Fièvres hémorragiques virales</span></span><br>\n              <span class=\"nc-red_bg\">Infections émergentes graves à </span><span><span class=\"nc-red_bg\">coronavirus</span></span><br>\n              <span><span class=\"nc-purple_bg\">Tuberculose</span></span> <span><span class=\"nc-red nc-bold\">MDR</span></span> ou <span><span class=\"nc-red nc-bold\">XDR</span></span><br>\n              Souches émergentes de <span>grippe</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span>maladies hautement transmissibles</span></td>\n            <td>\n              <span><strong><span class=\"nc-orange_bg\">Variole</span></strong><span class=\"nc-orange_bg\"> et autres orthopoxvirus</span></span> (ex. <span>Monkeypox</span>)<br>\n              <span><strong><span class=\"nc-orange_bg\">Peste</span></strong></span> dans sa <span>forme pulmonaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : pour la <span class=\"nc-orange_bg\">peste</span>, c'est la <span>forme pulmonaire</span> qui relève des maladies hautement transmissibles (<span class=\"nc-red_bg\">transmission interhumaine</span> par voie respiratoire).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span><span class=\"nc-purple_bg\">Tuberculose</span></span> Enfant / Adulte · 166 — <span>Grippe</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition du bioterrorisme","contenu":"<div class=\"notion-course\"><p>Le <strong><span>bioterrorisme</span></strong> est l'<strong>utilisation</strong> — ou la <strong><span>menace d'utilisation</span></strong> — d'<strong><span class=\"nc-red nc-bold\">agents biologiques </span><span><span class=\"nc-red nc-bold\">comme une arme</span></span></strong>, en vue d'<span><span class=\"nc-red nc-bold\">induire une maladie ou la mort</span></span> chez <span>les</span> <span class=\"nc-orange_bg\">hommes</span>, les <span class=\"nc-orange_bg\">animaux</span> et/ou les <span class=\"nc-orange_bg\">plantes</span>.</p>\n      <p>Sous le terme <strong>« agent <span>biologique</span> »</strong>, on regroupe :</p>\n      <ul>\n        <li><span>les</span> <span><span class=\"nc-purple_bg\">agents infectieux naturels</span></span> : bactéries, virus, parasites, champignons ;</li>\n        <li><span>les</span> <span><span class=\"nc-purple_bg\">toxines</span></span><span class=\"nc-purple_bg\"> produites par ces agents </span><span><span class=\"nc-purple_bg\">infectieux</span></span><span class=\"nc-purple_bg\"> naturels</span> ;</li>\n        <li><span>les</span> <span><span class=\"nc-purple_bg\">agents infectieux génétiquement modifiés</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ Piège classique : le bioterrorisme inclut la <strong><span>menace</span></strong> d'utilisation (pas seulement l'usage effectif) et englobe <span>les</span> <strong><span>agents génétiquement modifiés</span></strong> — deux points souvent oubliés.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"178-7","rang":"B","rubrique":"Définition","titre":"Connaître la classification des principaux agents biologiques utilisables dans un contexte de bioterrorisme","contenu":"<div class=\"notion-course\"><p><span>Les</span> principaux agents biologiques du bioterrorisme sont classés selon leur <strong>niveau de risque</strong>, par ordre <strong>décroissant</strong> — catégories A, B puis C.</p>\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Définition</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Catégorie A</span></td>\n            <td><span class=\"nc-red_bg\">Maladies </span><strong><span class=\"nc-red_bg\">létales et hautement transmissibles</span></strong><span class=\"nc-red_bg\">, ou </span><strong><span class=\"nc-red_bg\">faciles à disséminer</span></strong> — priorité absolue</td>\n            <td>\n              <strong>Bactéries :</strong> <span><em><span class=\"nc-red nc-bold\">Bacillus anthracis</span></em></span> ; <span><em><span class=\"nc-red nc-bold\">Yersinia pestis</span></em></span> ; <span><em><span class=\"nc-red nc-bold\">Francisella tularensis</span></em></span><br>\n              <strong>Virus :</strong> <span>virus de la <span class=\"nc-red nc-bold\">variole</span></span> ; <span>Filovirus (<span class=\"nc-red nc-bold\">Ebola</span>, <span class=\"nc-red nc-bold\">Marburg</span>)</span> ; <span>Arenavirus (<span class=\"nc-red nc-bold\">Lassa</span>, Junin)</span><br>\n              <strong>Toxines :</strong> <span><span class=\"nc-red nc-bold\">toxines de </span><em><span class=\"nc-red nc-bold\">Clostridium botulinum</span></em> (toxines botuliques)</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Catégorie B</span></td>\n            <td>Pathogénicité <strong>modérée</strong>, <span>mortalité</span> plus faible</td>\n            <td>\n              <strong>Bactéries :</strong> <span><em>Coxiella burnetii</em></span> ; <span><em>Brucella</em></span> ; <span><em>Burkholderia mallei</em> et <em>pseudomallei</em></span><br>\n              <strong>Virus :</strong> <span>Alphavirus (encéphalites équines du Venezuela, de l'Est et de l'Ouest)</span><br>\n              <strong>Toxines :</strong> <span>ricine</span> ; <span>toxine epsilon de <em>Clostridium perfringens</em></span> ; <span>entérotoxine B staphylococcique</span><br>\n              <strong><span class=\"nc-purple_bg\">Pathogènes transmis par l'eau et </span><span><span class=\"nc-purple_bg\">les</span></span><span class=\"nc-purple_bg\"> aliments</span> :</strong> <span><em>Salmonella</em></span> ; <span><em>Shigella dysenteriae</em></span> ; <span><em>E. coli</em> O157:H7</span> ; <span><em>Vibrio cholerae</em></span> ; <span><em>Cryptosporidium parvum</em></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Catégorie C</span></td>\n            <td><span class=\"nc-blue_bg\">Maladies infectieuses </span><strong><span class=\"nc-blue_bg\">émergentes</span></strong><span class=\"nc-blue_bg\"> faciles à disséminer</span></td>\n            <td>Virus <span>Nipah</span> ; <span>Hantavirus</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Voies de contamination possibles :</strong></p>\n      <ul>\n        <li><span><strong>Percutanée</strong></span> ;</li>\n        <li><span><strong>Digestive</strong> — ingestion d'eau ou d'aliments</span> ;</li>\n        <li><span><strong>Aérosols</strong></span> — particules de <span>1 à 5 µm</span> de <span>diamètre</span>, susceptibles de rester en suspension dans l'<span>air</span> plusieurs heures et, en cas d'inhalation, d'atteindre <span>les</span> <span>alvéoles pulmonaires</span>.</li>\n      </ul>\n      <p><strong>Classement selon la conséquence :</strong></p>\n      <ul>\n        <li><span><strong>Agents létaux :</strong></span> <span><em><span class=\"nc-red nc-bold\">Bacillus anthracis</span></em></span>, <span><em><span class=\"nc-red nc-bold\">Yersinia pestis</span></em></span>, <span><span class=\"nc-red nc-bold\">variole</span></span>… ;</li>\n        <li><strong>Agents incapacitants :</strong> <span><em>Coxiella burnetii</em></span>, <span><em>Brucella</em></span>, <span>entérotoxine B staphylococcique</span>…</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ À retenir : <span>les</span> agents à connaître en priorité sont ceux de la <span>catégorie A</span>. Ne pas confondre les <strong>toxines botuliques</strong> (catégorie A) avec les autres toxines — ricine, entérotoxine B (catégorie B).</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les agents de la classification historique de bioterrorisme n’ont pas tous une <span class=\"nc-red_bg\">transmission interhumaine</span> : charbon et botulisme n’imposent pas le même isolement qu’une infection contagieuse. Reconnaissance clinique, soins urgents et alerte spécialisée guident la conduite.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 178</a></li><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"principes":"<p>Suivre les définitions, la prévention et la surveillance détaillées dans les objectifs de cette fiche.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf","label":"Collège Pilly — Risques émergents (item 178, PDF)"}],"cards":[{"i":"0ff928125352","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"Une infection doit-elle être à la fois nouvelle et croissante pour être dite émergente ?","a":"<div class=\"notion-course\"><ul><li>Une infection émergente est nouvellement apparue, nouvellement reconnue, ou augmente en incidence/extension ; une infection connue qui réapparaît est réémergente.</li></ul></div>"},{"i":"6f81049a1834","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"Comment définit-on une infection émergente ou réémergente ?","a":"<div class=\"notion-course\"><ul><li>Une infection émergente est nouvellement apparue, nouvellement reconnue, ou augmente en incidence/extension ; une infection connue qui réapparaît est réémergente.</li></ul></div>"},{"i":"ada1fd928d7f","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"Quels sont les principaux types de risques émergents biologiques ?","a":"<div class=\"notion-course\"><ul><li>Mécanismes : changements de l’agent, des hôtes, des vecteurs et de l’environnement, mobilités, contacts humains–animaux, fragilisation des systèmes de santé et résistances.</li></ul></div>"},{"i":"041db1b35d1c","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Est-ce qu'une maladie connue peut être considérée comme une maladie infectieuse émergente (MIE) ?","a":"<div class=\"notion-course\"><p>Oui, absolument. Une maladie connue peut être une MIE si son <strong>incidence est en augmentation</strong>, si ses <strong>caractéristiques ont changé</strong>, ou si les <strong>conditions de son expansion sont nouvelles</strong> ou réunies. Il est important de ne pas exclure une maladie car elle n'est pas \"nouvelle\" dans ce contexte.</p></div>"},{"i":"5662648bc84d","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Quelle est la définition d'une maladie infectieuse émergente (MIE) ?","a":"<div class=\"notion-course\"><p>Une maladie infectieuse émergente (MIE) est une maladie infectieuse, ou présumée infectieuse, à la fois <strong>nouvelle et en augmentation</strong>, touchant l'homme, l'animal ou les deux.</p></div>"},{"i":"cee04c26728c","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Quels sont les trois scénarios conduisant à la définition d'une maladie infectieuse émergente (MIE) ?","a":"<div class=\"notion-course\"><ul><li>Une <span class=\"nc-yellow_bg\">entité clinique d'origine infectieuse </span><strong><span class=\"nc-yellow_bg\">nouvellement apparue ou identifiée</span></strong> (pathologie jamais décrite).</li><li>Une maladie connue dont l'<strong>incidence est en augmentation</strong> ou dont les <strong>caractéristiques cliniques ou évolutives ont changé</strong> dans une population donnée.</li><li>Une <span class=\"nc-yellow_bg\">maladie identifiée dont les </span><strong><span class=\"nc-yellow_bg\">conditions d'expansion sont réunies</span> ou anticipées</strong> (par exemple, un vecteur).</li></ul></div>"},{"i":"38452427bc17","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"L’absence de traitement ou de vaccin est-elle nécessaire pour définir une menace infectieuse importante ?","a":"<div class=\"notion-course\"><ul><li>Une menace infectieuse se caractérise par son potentiel de diffusion, sa gravité et les moyens de contrôle disponibles. L’absence de traitement ou de vaccin n’est pas un critère obligatoire : des infections à haut risque disposent désormais de vaccins et/ou traitements.</li></ul></div>"},{"i":"98dabacc0f1f","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"Quels paramètres distinguer pour caractériser une menace infectieuse ?","a":"<div class=\"notion-course\"><ul><li>Une menace infectieuse se caractérise par son potentiel de diffusion, sa gravité et les moyens de contrôle disponibles. L’absence de traitement ou de vaccin n’est pas un critère obligatoire : des infections à haut risque disposent désormais de vaccins et/ou traitements.</li><li>Alerte selon le circuit ARS/Santé publique France et recours aux équipes spécialisées ; les mesures doivent suivre l’agent et le contexte épidémiologique actuels, sans considérer toutes les infections émergentes comme également contagieuses.</li></ul></div>"},{"i":"ec925b2e2acf","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"Quelle est la définition d'une maladie hautement transmissible ?","a":"<div class=\"notion-course\"><ul><li>Infection ayant un potentiel élevé de diffusion dans les conditions considérées. Distinguer transmissibilité, gravité et moyens de prévention : une forte transmissibilité n’impose ni forte létalité ni <span class=\"nc-red_bg\">absence de vaccin</span>.</li></ul></div>"},{"i":"27bf56127a49","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Qu'est-ce qu'un agent biologique dans le cadre du bioterrorisme ?","a":"<div class=\"notion-course\"><p>Sous le terme « agent biologique », on regroupe :</p><ul><li>Les <strong><span class=\"nc-purple_bg\">agents infectieux naturels</span></strong> : bactéries, virus, parasites, champignons.</li><li>Les <strong><span class=\"nc-purple_bg\">toxines</span></strong><span class=\"nc-purple_bg\"> produites par ces agents infectieux naturels</span>.</li><li>Les <strong><span class=\"nc-purple_bg\">agents infectieux génétiquement modifiés</span></strong>.</li></ul></div>"},{"i":"682ec127bb3f","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Quel est un piège classique concernant la définition du bioterrorisme ?","a":"<div class=\"notion-course\"><p>Un piège classique est d'oublier que le bioterrorisme inclut la <strong>menace d'utilisation</strong> (pas seulement l'usage effectif) et qu'il englobe les <strong>agents génétiquement modifiés</strong>.</p></div>"},{"i":"adfdc57dfcb4","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Quelle est la définition du bioterrorisme ?","a":"<div class=\"notion-course\"><p>Le bioterrorisme est l'<strong>utilisation</strong> — ou la <strong>menace d'utilisation</strong> — d'<strong><span class=\"nc-red nc-bold\">agents biologiques</span></strong><span class=\"nc-red nc-bold\"> comme une arme</span>, en vue d'<strong><span class=\"nc-red nc-bold\">induire une maladie ou la mort</span></strong> chez les <span class=\"nc-orange_bg\">hommes</span>, les <span class=\"nc-orange_bg\">animaux</span> et/ou les <span class=\"nc-orange_bg\">plantes</span>.</p></div>"},{"i":"6747250475a5","n":178,"o":"178-3","u":"Définition","t":"Citer les principaux agents infectieux émergents ou réémergents","q":"Quels sont les points essentiels concernant citer les principaux agents infectieux émergents ou réémergents ?","a":"<div class=\"notion-course\"><p><span>Les</span> agents <span>infectieux</span> émergents ou réémergents se répartissent entre ceux <strong>communs</strong> aux MIE et aux maladies hautement transmissibles, et ceux <strong>spécifiques</strong> aux MIE.</p>\n      <table>\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(<span>MIE</span> et maladies hautement transmissibles)</td>\n            <td>\n              <strong><span class=\"nc-red_bg\">Fièvres hémorragiques virales</span> :</strong> <span><span class=\"nc-red nc-bold\">Ebola</span></span> ; <span><span class=\"nc-red nc-bold\">Marburg</span></span> ; <span><span class=\"nc-red nc-bold\">Crimée-Congo</span></span> ; <span><span class=\"nc-red nc-bold\">Lassa</span></span><br>\n              <strong>Coronavirus émergents graves :</strong> <span><span class=\"nc-red nc-bold\">SRAS</span></span> ; <span><span class=\"nc-red nc-bold\">MERS</span></span> ; <span><span class=\"nc-red nc-bold\">COVID-19</span></span><br>\n              <strong><span><span class=\"nc-purple_bg\">Tuberculose</span></span> résistante :</strong> multi-résistante (<span><span class=\"nc-red nc-bold\">MDR</span></span>) ou ultra-résistante (<span><span class=\"nc-red nc-bold\">XDR</span></span>)<br>\n              <strong>Grippes :</strong> <span><span class=\"nc-purple_bg\">grippe aviaire</span></span> et <span><span class=\"nc-purple_bg\">grippe pandémique</span></span> (<span><em>Myxovirus influenzae</em> H5N1</span> et futures souches porteuses d'autres H et N)\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span>MIE</span></td>\n            <td>\n              <strong><span class=\"nc-purple_bg\">Encéphalites virales</span> :</strong> virus <span>West-Nile</span> ; virus <span>Nipah</span> ; virus <span>Hendra</span><br>\n              <strong><span class=\"nc-purple_bg\">Arboviroses</span></strong> (transmises par <span><em>Aedes aegypti</em></span> et <span><em>Aedes albopictus</em></span>) : <span>Chikungunya</span> ; <span>dengue</span> ; <span>Zika</span><br>\n              <strong><span>IST</span> :</strong> <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span><span class=\"nc-purple_bg\">syphilis</span></span> ; <span><span class=\"nc-purple_bg\">lymphogranulomatose vénérienne</span></span><br>\n              <strong><span class=\"nc-purple_bg\">SHU</span></strong><span class=\"nc-purple_bg\"> (syndrome hémolytique et urémique)</span> : <span><em>E. coli</em> O157:H7</span><br>\n              <strong><span class=\"nc-red_bg\">Infections graves à </span><span><em><span class=\"nc-red_bg\">Clostridium difficile</span></em></span> :</strong> <span><em>C. difficile</em> O27 hypervirulent</span><br>\n              <strong>BHR</strong> (bactéries hautement résistantes) : entérobactéries productrices de <span>carbapénémase</span> ; <span>entérocoque</span> résistant aux <span>glycopeptides</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span>Méningite</span> - <span>méningoencéphalite</span> · 159 — <span><span class=\"nc-purple_bg\">Tuberculose</span></span> Enfant / Adulte · 166 — <span>Grippe</span> · 167 — Hépatites virales · 169 — VIH · 176 — <span>Diarrhée</span> infectieuse</em></p></div>"},{"i":"7dbd2614c420","n":178,"o":"178-5","u":"Définition","t":"Citer les principaux agents infectieux responsables de maladies hautement transmissibles","q":"Quels sont les points essentiels concernant citer les principaux agents infectieux responsables de maladies hautement transmissibles ?","a":"<div class=\"notion-course\"><p><span>Les</span> agents responsables de maladies hautement transmissibles se répartissent entre ceux <strong>communs</strong> aux MIE et ceux <strong>spécifiques</strong> aux maladies hautement transmissibles.</p>\n      <table>\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(partagés avec <span>les</span> <span>MIE</span>)</td>\n            <td>\n              <span><span class=\"nc-red_bg\">Fièvres hémorragiques virales</span></span><br>\n              <span class=\"nc-red_bg\">Infections émergentes graves à </span><span><span class=\"nc-red_bg\">coronavirus</span></span><br>\n              <span><span class=\"nc-purple_bg\">Tuberculose</span></span> <span><span class=\"nc-red nc-bold\">MDR</span></span> ou <span><span class=\"nc-red nc-bold\">XDR</span></span><br>\n              Souches émergentes de <span>grippe</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span>maladies hautement transmissibles</span></td>\n            <td>\n              <span><strong><span class=\"nc-orange_bg\">Variole</span></strong><span class=\"nc-orange_bg\"> et autres orthopoxvirus</span></span> (ex. <span>Monkeypox</span>)<br>\n              <span><strong><span class=\"nc-orange_bg\">Peste</span></strong></span> dans sa <span>forme pulmonaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : pour la <span class=\"nc-orange_bg\">peste</span>, c'est la <span>forme pulmonaire</span> qui relève des maladies hautement transmissibles (<span class=\"nc-red_bg\">transmission interhumaine</span> par voie respiratoire).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span><span class=\"nc-purple_bg\">Tuberculose</span></span> Enfant / Adulte · 166 — <span>Grippe</span></em></p></div>"},{"i":"482bee122e69","n":178,"o":"178-7","u":"Définition","t":"Connaître la classification des principaux agents biologiques utilisables dans un contexte de bioterrorisme","q":"Quels sont les points essentiels concernant la classification des principaux agents biologiques utilisables dans un contexte de bioterrorisme ?","a":"<div class=\"notion-course\"><p><span>Les</span> principaux agents biologiques du bioterrorisme sont classés selon leur <strong>niveau de risque</strong>, par ordre <strong>décroissant</strong> — catégories A, B puis C.</p>\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Définition</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Catégorie A</span></td>\n            <td><span class=\"nc-red_bg\">Maladies </span><strong><span class=\"nc-red_bg\">létales et hautement transmissibles</span></strong><span class=\"nc-red_bg\">, ou </span><strong><span class=\"nc-red_bg\">faciles à disséminer</span></strong> — priorité absolue</td>\n            <td>\n              <strong>Bactéries :</strong> <span><em><span class=\"nc-red nc-bold\">Bacillus anthracis</span></em></span> ; <span><em><span class=\"nc-red nc-bold\">Yersinia pestis</span></em></span> ; <span><em><span class=\"nc-red nc-bold\">Francisella tularensis</span></em></span><br>\n              <strong>Virus :</strong> <span>virus de la <span class=\"nc-red nc-bold\">variole</span></span> ; <span>Filovirus (<span class=\"nc-red nc-bold\">Ebola</span>, <span class=\"nc-red nc-bold\">Marburg</span>)</span> ; <span>Arenavirus (<span class=\"nc-red nc-bold\">Lassa</span>, Junin)</span><br>\n              <strong>Toxines :</strong> <span><span class=\"nc-red nc-bold\">toxines de </span><em><span class=\"nc-red nc-bold\">Clostridium botulinum</span></em> (toxines botuliques)</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Catégorie B</span></td>\n            <td>Pathogénicité <strong>modérée</strong>, <span>mortalité</span> plus faible</td>\n            <td>\n              <strong>Bactéries :</strong> <span><em>Coxiella burnetii</em></span> ; <span><em>Brucella</em></span> ; <span><em>Burkholderia mallei</em> et <em>pseudomallei</em></span><br>\n              <strong>Virus :</strong> <span>Alphavirus (encéphalites équines du Venezuela, de l'Est et de l'Ouest)</span><br>\n              <strong>Toxines :</strong> <span>ricine</span> ; <span>toxine epsilon de <em>Clostridium perfringens</em></span> ; <span>entérotoxine B staphylococcique</span><br>\n              <strong><span class=\"nc-purple_bg\">Pathogènes transmis par l'eau et </span><span><span class=\"nc-purple_bg\">les</span></span><span class=\"nc-purple_bg\"> aliments</span> :</strong> <span><em>Salmonella</em></span> ; <span><em>Shigella dysenteriae</em></span> ; <span><em>E. coli</em> O157:H7</span> ; <span><em>Vibrio cholerae</em></span> ; <span><em>Cryptosporidium parvum</em></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Catégorie C</span></td>\n            <td><span class=\"nc-blue_bg\">Maladies infectieuses </span><strong><span class=\"nc-blue_bg\">émergentes</span></strong><span class=\"nc-blue_bg\"> faciles à disséminer</span></td>\n            <td>Virus <span>Nipah</span> ; <span>Hantavirus</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Voies de contamination possibles :</strong></p>\n      <ul>\n        <li><span><strong>Percutanée</strong></span> ;</li>\n        <li><span><strong>Digestive</strong> — ingestion d'eau ou d'aliments</span> ;</li>\n        <li><span><strong>Aérosols</strong></span> — particules de <span>1 à 5 µm</span> de <span>diamètre</span>, susceptibles de rester en suspension dans l'<span>air</span> plusieurs heures et, en cas d'inhalation, d'atteindre <span>les</span> <span>alvéoles pulmonaires</span>.</li>\n      </ul>\n      <p><strong>Classement selon la conséquence :</strong></p>\n      <ul>\n        <li><span><strong>Agents létaux :</strong></span> <span><em><span class=\"nc-red nc-bold\">Bacillus anthracis</span></em></span>, <span><em><span class=\"nc-red nc-bold\">Yersinia pestis</span></em></span>, <span><span class=\"nc-red nc-bold\">variole</span></span>… ;</li>\n        <li><strong>Agents incapacitants :</strong> <span><em>Coxiella burnetii</em></span>, <span><em>Brucella</em></span>, <span>entérotoxine B staphylococcique</span>…</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ À retenir : <span>les</span> agents à connaître en priorité sont ceux de la <span>catégorie A</span>. Ne pas confondre les <strong>toxines botuliques</strong> (catégorie A) avec les autres toxines — ricine, entérotoxine B (catégorie B).</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les agents de la classification historique de bioterrorisme n’ont pas tous une <span class=\"nc-red_bg\">transmission interhumaine</span> : charbon et botulisme n’imposent pas le même isolement qu’une infection contagieuse. Reconnaissance clinique, soins urgents et alerte spécialisée guident la conduite.</li></ul></div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941810eac69fa72ecc7ef2a?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
